package io.github.miclean.tests;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import io.github.miclean.module.skip.*;

/** Isolated disabled subscriptions only. No real subscription updates or permission changes. */
public final class SubscriptionEditorSmoke extends Instrumentation {
    private volatile Activity current;private SkipRepository repo;private int checks;private long openMs;
    private final long id=202610280128L,localId=-202610280128L;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
    private void check(boolean yes,String reason){checks++;if(!yes)throw new AssertionError(reason);}
    private void main(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}
    private View tag(View root,String tag){if(tag.equals(root.getTag()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=tag(((ViewGroup)root).getChildAt(i),tag);if(v!=null)return v;}return null;}
    private TextView text(View root,String label){if(root instanceof TextView&&label.contentEquals(((TextView)root).getText()))return (TextView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){TextView v=text(((ViewGroup)root).getChildAt(i),label);if(v!=null)return v;}return null;}
    private View root(){return current.getWindow().getDecorView();}
    private AlertDialog dialog(String field){try{java.lang.reflect.Field f=current.getClass().getDeclaredField("actions");f.setAccessible(true);Object owner=f.get(current);f=owner.getClass().getDeclaredField(field);f.setAccessible(true);return (AlertDialog)f.get(owner);}catch(Exception e){throw new AssertionError(e);}}
    private void click(String label){main(()->{TextView v=text(root(),label);check(v!=null,"Missing menu: "+label);v.performClick();});waitForIdleSync();}
    private void open(long sourceId){main(()->{try{current.startActivity(new Intent(current,Class.forName("io.github.miclean.module.SmartSkipActivity")).putExtra("source_id",sourceId));}catch(Exception e){throw new RuntimeException(e);}});for(int i=0;i<80;i++){boolean[] ready={false};main(()->ready[0]=current.getClass().getSimpleName().equals("SmartSkipActivity")&&text(root(),"编辑订阅  ›")!=null);if(ready[0])break;SystemClock.sleep(50);}waitForIdleSync();}
    private void awaitSource(boolean present){for(int i=0;i<160;i++){if(repo.getSources().list().stream().anyMatch(s->s.getId()==id)==present)return;SystemClock.sleep(50);}throw new AssertionError("Save/delete timed out");}
    private void capture(AlertDialog d,String name){main(()->{View v=d.getWindow().getDecorView();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(v.getWidth(),v.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getCacheDir(),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}});}
    @Override public void onStart(){Bundle result=new Bundle();String phase="startup";java.util.concurrent.CountDownLatch releaseNetwork=new java.util.concurrent.CountDownLatch(1);
        try{
            for(int i=0;i<80&&current==null;i++)SystemClock.sleep(100);check(current!=null,"No main activity");repo=SkipRepository.get(getTargetContext());check(repo.getSources().list().stream().noneMatch(s->s.getId()==id||s.getId()==localId),"Reserved test IDs used");
            phase="fixtures";char[] dense=new char[3_000_000];Arrays.fill(dense,'x');String document="{id:"+id+",name:'NoAdMi 订阅弹窗验证',version:1,apps:[]/*"+new String(dense)+"🙂末尾*/}";
            repo.getSources().add(document,"https://example.invalid/subscription.json5",false);repo.getSources().find(id).getName();repo.getSources().add("{id:"+localId+",name:'NoAdMi 本地弹窗验证',version:1,apps:[]}","",false);repo.getSources().find(localId).getName();SkipRepository.executor.execute(()->{try{releaseNetwork.await(90,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException ignored){}});open(id);
            main(()->{for(String label:new String[]{"编辑订阅  ›","规则分类  ›","应用规则  ›","全局规则  ›"})check(text(root(),label)!=null,"Expected menu missing "+label);for(String label:new String[]{"复制订阅链接","编辑订阅链接  ›","更新此订阅","删除订阅","查看订阅 JSON5","编辑订阅 JSON5"})check(text(root(),label)==null,"Old redundant entry remains "+label);});
            click("编辑订阅  ›");waitForIdleSync();
            phase="large raw viewer";main(()->{long before=SystemClock.elapsedRealtime();tag(dialog("editorDialog").getWindow().getDecorView(),"subscription_edit_view_document").performClick();openMs=SystemClock.elapsedRealtime()-before;check(openMs<750,"Viewer blocked UI "+openMs+"ms");});
            for(int i=0;i<120;i++){boolean[] ready={false};main(()->{AlertDialog d=dialog("documentDialog");ListView list=(ListView)tag(d.getWindow().getDecorView(),"subscription_document_list");ready[0]=list.getAdapter()!=null;});if(ready[0])break;SystemClock.sleep(50);}waitForIdleSync();
            main(()->{AlertDialog d=dialog("documentDialog");ListView list=(ListView)tag(d.getWindow().getDecorView(),"subscription_document_list");check(list.getAdapter()!=null&&list.getAdapter().getCount()>1400,"Large document was truncated");check(list.getChildCount()<10,"Full document rows were created eagerly");for(int i=0;i<list.getChildCount();i++){check(list.getChildAt(i) instanceof TextView&&!(list.getChildAt(i) instanceof EditText),"Readonly viewer still uses editor");check(((TextView)list.getChildAt(i)).length()<=2048,"Unbounded visible text row");}int last=list.getAdapter().getCount()-1;check(list.getAdapter().getItem(last).toString().endsWith("🙂末尾*/}"),"Document tail lost");list.setSelection(last);});waitForIdleSync();capture(dialog("documentDialog"),"subscription-raw-0128.png");main(()->dialog("documentDialog").getButton(-2).performClick());
            phase="editor layout";waitForIdleSync();AlertDialog edit=dialog("editorDialog");main(()->check(edit.isShowing(),"Closing viewer lost parent editor"));
            main(()->{View view=edit.getWindow().getDecorView();LinearLayout header=(LinearLayout)tag(view,"subscription_edit_header");View copy=tag(view,"subscription_edit_copy"),update=tag(view,"subscription_edit_update");check(header.indexOfChild(copy)<header.indexOfChild(update),"Copy not left of update");check(update.getParent()==header&&copy.getParent()==header,"Actions not in header");check(copy.getLeft()<update.getLeft(),"Header order differs from screen position");check(edit.getButton(-3).getLeft()<edit.getButton(-1).getLeft(),"Delete not bottom-left");check(edit.getButton(-3).getTop()>=edit.getButton(-1).getTop(),"Delete not on footer row");copy.performClick();ClipboardManager clipboard=(ClipboardManager)current.getSystemService(Context.CLIPBOARD_SERVICE);check(repo.getSources().find(id).getUrl().contentEquals(clipboard.getPrimaryClip().getItemAt(0).getText()),"Link copy wrong");EditText input=(EditText)tag(view,"subscription_url");input.setText("http://invalid.test");update.performClick();check(input.getError()!=null,"Update accepted HTTP");check(repo.getSources().find(id).getUrl().equals("https://example.invalid/subscription.json5"),"Invalid update changed link");input.setText("https://example.invalid/edited.json5");check(input.getError()==null,"Corrected URL kept stale error");});capture(edit,"subscription-edit-0128.png");
            phase="save URL";main(()->edit.getButton(-1).performClick());for(int i=0;i<160&&!repo.getSources().find(id).getUrl().endsWith("edited.json5");i++)SystemClock.sleep(50);check(repo.getSources().find(id).getUrl().endsWith("edited.json5"),"New URL not persisted");check(repo.getSources().find(id).getDocument().equals(document),"Saving URL changed document");waitForIdleSync();
            phase="delete confirmation";click("编辑订阅  ›");AlertDialog parent=dialog("editorDialog");main(()->parent.getButton(-3).performClick());AlertDialog confirm=dialog("confirmationDialog");main(()->{check(confirm!=null&&confirm.isShowing(),"Delete has no confirmation");check(repo.getSources().list().stream().anyMatch(s->s.getId()==id),"Deleted before confirmation");confirm.getButton(-2).performClick();check(parent.isShowing(),"Cancel closed editor");parent.getButton(-3).performClick();dialog("confirmationDialog").getButton(-1).performClick();});awaitSource(false);waitForIdleSync();check(!parent.isShowing(),"Editor remains after deletion");
            phase="local subscription";open(localId);click("编辑订阅  ›");waitForIdleSync();capture(dialog("editorDialog"),"subscription-local-0128.png");main(()->{AlertDialog d=dialog("editorDialog");View v=d.getWindow().getDecorView();check(tag(v,"subscription_edit_copy")==null&&tag(v,"subscription_edit_update")==null,"Local subscription exposes invalid remote actions");check(d.getButton(-3).isShown(),"Local deletion missing");d.getButton(-3).performClick();dialog("confirmationDialog").getButton(-2).performClick();d.getButton(-2).performClick();});check(repo.getSources().list().stream().anyMatch(s->s.getId()==localId),"Canceled local deletion removed source");
            result.putString("stream","PASS: "+checks+" subscription editor checks; 3MB minified JSON5 open main thread="+openMs+"ms, bounded recycled rows and intact Unicode tail; simplified menus; top-right update with copy on left; footer delete with cancel/confirmation; copied and edited link; HTTP rejection; local subscription actions; save and deletion complete with the automatic-update queue blocked.\n");
        }catch(Throwable error){result.putString("stream","FAIL phase="+phase+": "+error+"\n");}
        finally{releaseNetwork.countDown();if(repo!=null)for(long key:new long[]{id,localId})if(repo.getSources().list().stream().anyMatch(s->s.getId()==key))repo.getSources().remove(key);}
        finish(result.getString("stream","").startsWith("PASS:")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
